 const tasks=state.data.tasks,stats=el('div','stats');for(const [label,value,note] of [['Active projects',state.data.projects.filter(x=>x.status==='active').length,'in this workspace'],['Awaiting approval',tasks.filter(x=>['AWAITING_APPROVAL','VERIFIED'].includes(x.state)).length,'owner decisions'],['Accepted tasks',tasks.filter(x=>x.parent_id&&x.state==='COMPLETED').length,'reviewed work'],['Blockers',tasks.filter(x=>['FAILED','BLOCKED'].includes(x.state)).length,'need attention']])add(stats,add(el('div','stat'),p(label),el('strong','',value),el('small','',note)));root.append(stats);
