function approvals(root){const groups=[['Plans awaiting approval',t=>t.state==='AWAITING_APPROVAL'],['Live dispatch authorization',t=>t.parent_id&&t.state==='ASSIGNED'||!t.parent_id&&t.state==='PLANNING'],['Test evidence & senior review',t=>t.state==='AWAITING_REVIEW'],['Requested corrections',t=>t.state==='CHANGES_REQUESTED'],['Final owner acceptance',t=>t.state==='VERIFIED']];for(const [title,filter]of groups){const panelEl=panel(title),tasks=state.data.tasks.filter(filter);if(!tasks.length)panelEl.append(empty('Nothing waiting here.'));for(const t of tasks){const card=button('',()=>openProject(t.project_id,t.task_id),'project-card');add(card,add(el('div','row'),el('h3','',t.description),badge(t.state)),p(state.data.projects.find(p=>p.id===t.project_id)?.name||'Project'),el('small','','Open decision controls →'));panelEl.append(card);}root.append(panelEl);}}
