// Refresh saved round history only while a loop is active and the owner is not typing.
setTimeout(async function messengerTick(){try{if(!document.hidden&&!state.busy&&['team','demo'].includes(state.view)&&state.data?.bigThree?.messenger?.loops.some(loop=>['running','waiting'].includes(loop.status))&&!document.activeElement?.matches?.('input,textarea,select'))await refresh();}catch{}finally{setTimeout(messengerTick,5000);}},5000);
